const state={projects:[],project:null,workflow:null,jobs:[],selectedStage:null,settings:null,logs:null,openPanels:{},assetToRemove:null,jobPage:1,costPage:1,pageSize:10};
const renderMusicBase=renderMusic;
renderMusic=(stage)=>{
  const stale=stage.data.inputs_changed?'<div class="truth-banner warning">已读取新素材。下方旧分析仅供对照，请点击“开始分析音乐与歌词”生成当前版本。</div>':"";
  return stale+renderMusicBase(stage);
};
const planningRunPanelBase=planningRunPanel;
planningRunPanel=()=>{
  const runs=state.workflow?.runs||[];
  if(runs.some(item=>["queued","running"].includes(item.runtime_state)))return planningRunPanelBase();
  const latest=runs.find(item=>item.operation==="animatic");
  if(latest?.runtime_state==="succeeded")return "";
  const candidate=runs.find(item=>item.can_resume);
  if(!candidate)return planningRunPanelBase();
  state.workflow.runs=[candidate,...runs.filter(item=>item!==candidate)];
  const panel=planningRunPanelBase();
  state.workflow.runs=runs;
  return panel;
};
setInterval(()=>{
  if(state.jobs.some(item=>item.status.runtime_state==="queued"))refresh(true).catch(()=>{});
},1800);
const $=(id)=>document.getElementById(id);
const escapeHtml=(value)=>String(value??"").replace(/[&<>"']/g,(char)=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[char]);
const shortId=(value)=>value?`${value.slice(0,12)}...`:"-";
const money=(value,digits=8)=>`¥${Number(value||0).toFixed(digits)}`;
const statusName={completed:"已完成",awaiting_approval:"待确认",approved:"已确认",revision:"待修改",preview_only:"预览稿",pending:"待制作",locked:"未开始",test_output:"测试产物",preview:"可预览",queued:"等待中",running:"运行中",succeeded:"已完成",failed:"失败",blocked:"已阻塞",cancelled:"已取消"};
const operationName={analyze:"素材分析",animatic:"导演规划",compile:"编译分镜",generate:"生成单镜",render:"最终合成",qc:"质量验收"};
const promptNames={"prompt.translate_requested":"提示词中译英","content.localize_requested":"项目内容英译中","content.translate_requested":"项目内容中译英","asset.curate_requested":"人物素材筛选","lyrics.semantic_segment.requested":"歌词语义分析","relationship_map.draft_requested":"人物关系与故事框架","visual_score.creative_draft_requested":"视觉总谱与分镜","visual_score.quality_review_requested":"方案提升三档自审","image.background.generate_requested":"GPT-image-2 背景生成","image.keyframe.generate_requested":"GPT-image-2 组合首帧生成","video.shot.generate_requested":"单镜视频生成"};
const musicRoleName={intro:"前奏",verse:"主歌","pre-chorus":"副歌前段",chorus:"副歌",bridge:"桥段",outro:"尾奏"};
const shotSizeName={extreme_close:"极特写",close:"特写",medium:"中景",full:"全身",wide:"全景"};
const transitionName={none:"无转场",hard_cut:"直接切换",occlusion_cut:"遮挡切换",action_match:"动作匹配",crossfade:"交叉淡化",flash_white:"白闪",ink_wipe:"水墨擦除",light_wipe:"光线擦除",bridge_clip:"桥接镜头"};
const techniqueName={"2.5d":"2.5维动画",static:"静态画面",i2v:"图片生成视频",hybrid:"混合制作"};
const qcName={pass_gate_checked:"检查通过",pending_diagnosis:"等待诊断"};
const mediaFormatName={wav:"波形音频",mp3:"压缩音频",m4a:"苹果音频",flac:"无损音频",ogg:"开放音频",timed_lrc:"带时间歌词",timed_spreadsheet:"导演时间表",plain_text:"纯文本歌词",PNG:"透明图片",JPEG:"图片",WEBP:"网页图片"};

async function reportFrontendError(value){try{await fetch("/api/v1/logs/frontend",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message:String(value.message||"前端未知错误").slice(0,4000),path:String(value.path||"").split("?",1)[0].slice(0,500),method:String(value.method||"").slice(0,12),status:Number(value.status||0),project_id:state.project?.project_id||"",job_id:"",user_agent:navigator.userAgent.slice(0,500)})})}catch{}}
async function api(path,options={}){const response=await fetch(path,{headers:{"Content-Type":"application/json",...(options.headers||{})},...options});if(!response.ok){let message=`请求失败 (${response.status})`;try{const body=await response.json();message=typeof body.detail==="string"?body.detail:message}catch{}void reportFrontendError({message,path,method:options.method||"GET",status:response.status});throw new Error(message)}const type=response.headers.get("content-type")||"";return type.includes("json")?response.json():response.text()}
function toast(message){const node=$("toast");node.textContent=message;node.classList.add("visible");clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove("visible"),3000)}
function setConnection(ok){const node=$("service-state");node.className=`service-state ${ok?"ready":"error"}`;node.querySelector("span").textContent=ok?"本地服务已连接":"本地服务未连接"}
function fileUrl(path){return `/api/v1/projects/${encodeURIComponent(state.project.project_id)}/files?path=${encodeURIComponent(path)}`}
function duration(time){return Array.isArray(time)&&time.length===2?`${Number(time[0]).toFixed(1)} - ${Number(time[1]).toFixed(1)} 秒`:"-"}
function chineseValue(value){let text=String(value??"").trim();if(!/[\u3400-\u9fff]/.test(text)&&/[A-Za-z]/.test(text))return "";text=text.replace(/\bgroup_0*(\d+)\b/gi,(_,number)=>`第${Number(number)}段`).replace(/\bintro\b/gi,"前奏").replace(/\bchorus\b/gi,"副歌").replace(/\bverse\b/gi,"主歌");return text}
function editableContent(field,value,rows=2){return `<textarea class="inline-content-editor" data-content-field="${escapeHtml(field)}" rows="${rows}" placeholder="点击上方“生成中文展示稿”后可编辑">${escapeHtml(chineseValue(value))}</textarea>`}
function contentEditBar(stage){if(!["music","story","storyboard"].includes(stage.id))return "";const display=state.workflow?.display_content||{};if(!(display.available_fields>0))return "";const incomplete=(display.localized_fields||0)<display.available_fields;return `<div class="content-edit-bar"><div><strong>中文展示内容</strong><span>页面只保存中文；保存时会调用大语言模型生成英文执行稿并记录费用。</span></div>${incomplete?'<button class="secondary-button" type="button" data-localize-content>生成中文展示稿</button>':""}<button class="primary-button" type="button" data-save-content>保存中文修改</button></div>`}

function renderProjects(){const list=$("project-list");list.innerHTML=state.projects.map(project=>`<button type="button" class="project-item ${state.project?.project_id===project.project_id?"active":""}" data-project="${escapeHtml(project.project_id)}"><strong>${escapeHtml(project.display_name||project.slug)}</strong><span>项目编号 ${escapeHtml(shortId(project.project_id))}</span></button>`).join("");list.querySelectorAll("[data-project]").forEach(button=>button.addEventListener("click",()=>selectProject(button.dataset.project)))}
function renderProjectView(){const has=Boolean(state.project);$("empty-state").classList.toggle("hidden",has);$("project-view").classList.toggle("hidden",!has);if(!has)return;$("project-name").textContent=state.workflow?.project?.display_name||state.project.display_name||state.project.slug;renderWorkflow();renderJobs()}
function pagination(page,total,pageSize,kind){const pages=Math.max(1,Math.ceil(total/pageSize));if(total<=pageSize)return "";return `<nav class="pager" aria-label="${kind==="jobs"?"运行记录":"费用明细"}翻页"><button type="button" data-page-kind="${kind}" data-page-value="${page-1}" aria-label="上一页" title="上一页" ${page<=1?"disabled":""}>‹</button><span>第 ${page} / ${pages} 页</span><button type="button" data-page-kind="${kind}" data-page-value="${page+1}" aria-label="下一页" title="下一页" ${page>=pages?"disabled":""}>›</button></nav>`}
function renderCosts(){const costs=state.workflow?.costs||{total_yuan:0,by_type:{},entries:[]};$("cost-total").textContent=money(costs.total_yuan);$("cost-llm").textContent=money(costs.by_type?.llm);$("cost-image").textContent=money(costs.by_type?.image,2);$("cost-video").textContent=money(costs.by_type?.video,2);const entries=(costs.entries||[]).slice().reverse();const pages=Math.max(1,Math.ceil(entries.length/state.pageSize));state.costPage=Math.min(Math.max(1,state.costPage),pages);const start=(state.costPage-1)*state.pageSize;const rows=entries.slice(start,start+state.pageSize).map(entry=>`<div class="cost-row"><div><strong>${escapeHtml(promptNames[entry.step_id]||entry.step_id)}</strong><span>${entry.resource_type==="llm"?`输入 ${entry.input_tokens||0} / 缓存 ${entry.cache_read_tokens||0} / 输出 ${entry.output_tokens||0} 词元`:`${entry.quantity}${entry.resource_type==="video"?" 秒":" 张"}`}</span></div><b>${money(entry.amount_yuan)}</b></div>`).join("");$("cost-ledger").innerHTML=entries.length?rows+pagination(state.costPage,entries.length,state.pageSize,"costs"):'<div class="empty-inline">尚未产生模型或媒体费用</div>'}

function renderWorkflow(){if(!state.workflow)return;const workflow=state.workflow;$("current-stage-label").textContent=`当前：${workflow.current_stage_title}`;$("blocking-reason").textContent=workflow.blocking_reason||"";renderCosts();const stages=workflow.stages;if(!state.selectedStage||!stages.some(item=>item.id===state.selectedStage))state.selectedStage=workflow.current_stage_id;$("stage-rail").innerHTML=stages.map((stage,index)=>`<button type="button" class="rail-step ${state.selectedStage===stage.id?"active":""} ${stage.status}" data-stage="${escapeHtml(stage.id)}"><span class="step-index">${String(index+1).padStart(2,"0")}</span><span class="step-copy"><strong>${escapeHtml(stage.title)}</strong><small>${escapeHtml(statusName[stage.status]||stage.status)}</small></span>${stage.cost_yuan?`<b>${money(stage.cost_yuan)}</b>`:""}</button>`).join("");$("stage-rail").querySelectorAll("[data-stage]").forEach(button=>button.addEventListener("click",()=>{state.selectedStage=button.dataset.stage;renderWorkflow()}));const current=stages.find(item=>item.id===state.selectedStage)||stages[0];$("stage-workspace").innerHTML=renderStage(current);bindStageActions(current)}

function stageHead(stage){return `<header class="stage-head"><div><span class="stage-kicker">制作步骤</span><h2>${escapeHtml(stage.title)}</h2><p>${escapeHtml(stage.subtitle)}</p></div><div class="stage-state"><span class="state-pill ${escapeHtml(stage.status)}">${escapeHtml(statusName[stage.status]||stage.status)}</span><strong>${money(stage.cost_yuan)}</strong><small>本步骤费用</small></div></header>${stage.status==="preview_only"?'<div class="truth-banner">这份分镜来自自动测试流程，可供查看，但上游故事框架尚未由您确认，因此不能进入正式制作。</div>':""}`}
function nextStepBlock(stage){const running=state.jobs.some(item=>item.status.runtime_state==="running"||item.status.runtime_state==="queued");const guides={intake:{title:stage.status==="completed"?"素材已经识别完成":"先导入完整项目素材",text:stage.status==="completed"?"请核对音频、歌词、人物图片和可选背景参考；背景也可以稍后逐镜补充。":"点击页面右上角“导入项目素材”，选择包含全部物料的文件夹。"},music:{title:stage.status==="completed"?"音乐结构已经生成":"现在需要分析音乐与歌词",text:stage.status==="completed"?"请检查时间轴、段落和情绪。故事草稿也已生成，下一步进入“故事框架”确认。":"系统将调用大语言模型分析歌词语义、音乐段落和人物关系，同时生成待确认的故事与分镜草稿，并记录本次费用。",action:stage.status==="pending"?"开始分析音乐与歌词":""},story:{title:stage.status==="awaiting_approval"?"现在需要确认故事":"等待上一步完成",text:stage.status==="awaiting_approval"?"检查人物关系、情绪推进、高潮和结尾；确认后才能进入正式分镜确认。":stage.status==="revision"?"素材或故事要求已变化，需要重新生成策划稿。请回到“音乐与歌词”重新开始分析。":"先完成“音乐与歌词”分析。"},storyboard:{title:stage.status==="awaiting_approval"?"现在需要逐镜确认":"等待故事确认",text:stage.status==="awaiting_approval"?"逐镜核对人物、场景背景、构图、首尾帧和转场。没有现成背景时会明确标记为待生成。":"先在“故事框架”确认故事走向。"},keyframes:{title:stage.status==="approved"?"完整场景首帧已经确认":stage.status==="awaiting_approval"?"现在需要确认全部组合首帧":"为每镜补齐完整场景首帧",text:stage.status==="locked"?"先确认全部分镜，本步骤才会开放。":"上传或选择人物与背景组合后的完整场景首帧。全部镜头选定后，才能进入单镜视频。"},shots:{title:stage.status==="pending"?"关键帧门已通过":"等待关键帧确认",text:stage.status==="pending"?"可以按已批准完整场景首帧逐镜制作视频。":"每镜必须先选择并确认完整场景首帧，之后才能产生视频费用。"},composite:{title:"等待全部单镜完成",text:"所有镜头确认后，系统才能合成音频、字幕和画面并执行质量检查。"},delivery:{title:stage.status==="awaiting_approval"?"现在需要确认最终成片":"等待合成验收",text:stage.status==="awaiting_approval"?"播放最终文件并确认是否可以交付；确认前系统不会外发。":"合成和质量检查通过后，本步骤会显示最终文件。"}};const guide=guides[stage.id];if(!guide)return "";return `<section class="next-step ${guide.action?"actionable":""}"><div><span>下一步</span><strong>${escapeHtml(guide.title)}</strong><p>${escapeHtml(guide.text)}</p></div>${guide.action?`<button class="primary-button" type="button" data-run-planning ${running?"disabled":""}>${running?"分析任务运行中":escapeHtml(guide.action)}</button>`:""}</section>`}
function planningRunPanel(){const run=(state.workflow?.runs||[]).find(item=>item.operation==="animatic");if(!run)return "";const active=run.runtime_state==="running"||run.runtime_state==="queued";if(run.runtime_state==="succeeded")return "";const title=active?"分析任务正在运行":run.runtime_state==="failed"?"分析任务在当前步骤失败":"分析任务状态";const message=active?`当前处理：${run.checkpoint||"准备输入素材"}。页面会自动刷新进度。`:run.failure_message||"任务尚未完成。";return `<section class="planning-run ${escapeHtml(run.runtime_state)}"><div class="planning-run-head"><div><span>最近一次运行</span><strong>${escapeHtml(title)}</strong></div><b class="mini-status ${escapeHtml(run.runtime_state)}">${escapeHtml(statusName[run.runtime_state]||run.runtime_state)}</b></div><p>${escapeHtml(message)}</p><dl><div><dt>任务编号</dt><dd>${escapeHtml(run.job_id)}</dd></div><div><dt>已产生费用</dt><dd>${money(run.cost_yuan)}</dd></div><div><dt>续跑位置</dt><dd>${escapeHtml(run.checkpoint||"-")}</dd></div></dl>${run.can_resume?`<button class="primary-button" type="button" data-resume-planning="${escapeHtml(run.job_id)}">从失败步骤继续</button>`:""}</section>`}
function approvalBlock(stage){if(!["story","storyboard","keyframes","delivery"].includes(stage.id))return "";if(stage.decision)return `<div class="decision-record"><strong>${stage.decision.action==="approve"?"您已确认此步骤":"您已要求修改"}</strong><span>${escapeHtml(stage.decision.note||"未填写备注")} · ${escapeHtml(new Date(stage.decision.decided_at).toLocaleString("zh-CN"))}</span></div>`;if(!stage.can_approve&&stage.status!=="revision")return "";const blocked=stage.status==="revision"&&!stage.can_approve;const question=stage.id==="story"?"人物关系和故事走向是否正确？":stage.id==="storyboard"?"人物、背景与逐镜构图是否可以进入关键帧制作？":stage.id==="keyframes"?"全部完整场景首帧是否可以进入单镜视频制作？":"此版本是否可以对外交付？";return `<section class="approval-gate ${blocked?"blocked-gate":""}"><div><span>${blocked?"正式制作门禁":"需要您拍板"}</span><strong>${blocked?"当前结构测试稿不能批准，请填写要求后退回重做。":question}</strong></div><textarea id="decision-note" rows="2" placeholder="修改意见（退回时必填）"></textarea><div><button class="secondary-button" type="button" data-decision="request_revision">${blocked?"提交重做要求":"退回修改"}</button>${blocked?"":'<button class="primary-button" type="button" data-decision="approve">确认并进入下一步</button>'}</div></section>`}
function promptBlock(stage){if(!stage.prompts?.length)return `<section class="prompt-none"><strong>本步骤不调用生成模型</strong><span>这是确定性处理步骤，没有系统提示词或任务提示词，也不会产生 大语言模型词元 与费用。</span></section>`;const panel=`prompt-${stage.id}`;const promptState=stage.prompts.some(item=>item.used)?"当前中文提示词在本次运行中使用过":stage.prompts.some(item=>item.call_recorded)?"本次调用过，但当前文本已变化":"本次未调用";return `<details class="prompt-settings" data-panel="${panel}" ${state.openPanels[panel]?"open":""}><summary>提示词与高级设置 <span>${promptState}</span></summary><div class="prompt-settings-body">${stage.prompts.map(item=>{const status=item.used?`正式任务已使用 · ${escapeHtml(item.model)} · 输入 ${item.usage.input_tokens||0} / 输出 ${item.usage.output_tokens||0} 词元 · ${money(item.cost_yuan)}`:item.call_recorded?`有正式任务调用记录，但运行时提示词与当前文本不同 · ${escapeHtml(item.model)} · ${money(item.cost_yuan)}`:"正式任务未调用，不产生费用";const translation=item.translation||{};const translationStatus=translation.used?`已翻译 · 输入 ${translation.usage.input_tokens||0} / 输出 ${translation.usage.output_tokens||0} 词元 · ${money(translation.cost_yuan)}`:"本次未翻译";return `<section class="prompt-card"><header><div><strong>${escapeHtml(promptNames[item.key]||item.key)}</strong><small class="prompt-use ${item.used?"used":"unused"}">${status}</small></div></header><label><span><b>系统提示词</b><small>角色、输入边界、输出合同与禁止事项</small></span><textarea data-prompt-system="${escapeHtml(item.key)}" rows="8" maxlength="16000">${escapeHtml(item.system_text)}</textarea></label><label><span><b>任务提示词</b><small>当前步骤需要模型完成的具体工作</small></span><textarea data-prompt-task="${escapeHtml(item.key)}" rows="6" maxlength="16000">${escapeHtml(item.task_text)}</textarea></label><details class="translation-settings"><summary>运行时中文转英文 <span>${translationStatus}</span></summary><label><span><b>翻译系统提示词</b><small>翻译也会产生 大语言模型词元 与费用</small></span><textarea data-translation-system rows="6" maxlength="16000">${escapeHtml(translation.system_text||"")}</textarea></label><label><span><b>翻译任务提示词</b></span><textarea data-translation-task rows="4" maxlength="16000">${escapeHtml(translation.task_text||"")}</textarea></label></details></section>`}).join("")}<button class="secondary-button" data-save-prompts type="button">保存本步骤提示词</button></div></details>`}
function artifactBlock(stage){if(!stage.artifacts?.length)return "";const panel=`artifacts-${stage.id}`;return `<details class="artifact-paths" data-panel="${panel}" ${state.openPanels[panel]?"open":""}><summary>本步骤产物文件 <span>${stage.artifacts.length} 项</span></summary>${stage.artifacts.map(path=>`<div><code>${escapeHtml(path)}</code></div>`).join("")}</details>`}

function renderIntake(stage){const manifest=stage.data.manifest||{};const audio=manifest.audio||{};const lyrics=manifest.lyrics||{};const chars=manifest.characters||[];const removed=stage.data.removed_characters||[];const duplicateGroups=stage.data.duplicate_groups||[];const preferred=new Set(duplicateGroups.map(item=>item.preferred_path));const duplicates=new Set(duplicateGroups.flatMap(item=>item.candidate_paths));const aligned=["aligned","aligned_director_contract"].includes(lyrics.alignment_state);return `<div class="metric-row"><div><span>音频</span><strong>${audio.duration_seconds?`${Number(audio.duration_seconds).toFixed(1)} 秒`:"未识别"}</strong><small>${escapeHtml(mediaFormatName[audio.format]||"音频文件")} · ${escapeHtml(audio.sample_rate||"")} 赫兹</small></div><div><span>歌词</span><strong>${aligned?"时间轴已对齐":"待对齐"}</strong><small>${escapeHtml(mediaFormatName[lyrics.kind]||"歌词文件")}${lyrics.director_contract?` · ${lyrics.director_contract.entry_count} 个导演段`:""}</small></div><div><span>有效人物图片</span><strong>${chars.length} 张</strong><small>${duplicateGroups.length?`识别到 ${duplicateGroups.length} 组重复人物`:removed.length?`${removed.length} 张已移除，需重新分析`:"仅使用本地源图"}</small></div></div>${stage.data.assets_changed?'<div class="truth-banner warning">人物素材已变化。故事、分镜和后续产物继续保留供核对，但在重新分析前不能作为正式制作依据。</div>':""}<section class="content-section"><div class="section-heading"><h3>当前使用的人物图片</h3><span>请选择同一套清晰原始图，重复的 低分辨率与高分辨率 版本只保留一套</span></div><div class="asset-grid">${chars.map(item=>{const name=item.path.split("/").pop();const recommendation=duplicates.has(item.path)?(preferred.has(item.path)?"建议保留":"低清重复"):"";return `<figure><img src="${fileUrl(item.path)}" alt="人物素材"><figcaption>${recommendation?`<em class="asset-recommendation ${preferred.has(item.path)?"keep":"remove"}">${recommendation}</em>`:""}<strong>${escapeHtml(name)}</strong><span>${item.width} × ${item.height} · ${item.has_alpha?"透明背景":"无透明通道"}</span><button type="button" data-remove-asset="${escapeHtml(item.path)}" data-asset-name="${escapeHtml(name)}">从项目移除</button></figcaption></figure>`}).join("")||'<div class="empty-inline">当前没有有效人物图片</div>'}</div></section>${duplicateGroups.length?`<section class="content-section duplicate-summary"><div class="section-heading"><h3>重复素材建议</h3><span>只提供建议，不会自动删除</span></div>${duplicateGroups.map(item=>`<div><strong>${escapeHtml(item.person_label)}</strong><span>${escapeHtml(item.reason)}</span><code>建议保留 ${escapeHtml(item.preferred_path.split("/").pop())}</code></div>`).join("")}</section>`:""}${removed.length?`<section class="content-section removed-assets"><div class="section-heading"><h3>已移除素材</h3><span>文件仍在项目回收区</span></div>${removed.map(item=>`<div><span><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(new Date(item.removed_at).toLocaleString("zh-CN"))}</small></span><button class="secondary-button" type="button" data-restore-asset="${escapeHtml(item.original_path)}">恢复</button></div>`).join("")}</section>`:""}`}
function renderMusic(stage){const map=stage.data.music_map||{};const sections=map.sections||[];const entries=stage.data.director_entries||[];const contract=stage.data.director_contract||{};return `${planningRunPanel()}${contentEditBar(stage)}<div class="metric-row"><div><span>歌曲时长</span><strong>${Number(map.duration||0).toFixed(1)} 秒</strong></div><div><span>估算节拍速度</span><strong>${Number(map.bpm||0).toFixed(1)}</strong></div><div><span>歌词导演段</span><strong>${entries.length||sections.length} 段</strong><small>${contract.characters_are_binding?"人物出场已锁定":"未提供人物锁定"}</small></div></div>${entries.length?`<section class="content-section director-contract"><div class="section-heading"><div><h3>原始歌词导演表</h3><span>${escapeHtml(contract.sheet_name||"工作表")} · Excel 原始字段完整读取</span></div><em>人物与起止时间是硬约束，模型不能改写</em></div><div class="director-table"><div class="director-row director-head"><b>时间</b><b>人物</b><b>歌词</b><b>来源</b></div>${entries.map(item=>`<div class="director-row"><time>${duration([item.start_seconds,item.end_seconds])}</time><strong>${escapeHtml(item.character_label||(item.character_names||[]).join("＋"))}</strong><span>${escapeHtml(item.text)}</span><small>第 ${escapeHtml(item.source_row)} 行</small></div>`).join("")}</div></section>`:'<div class="truth-banner warning">当前项目没有完整的 Excel 导演约束。请重新导入原始 xlsx，旧 LRC 无法恢复已丢失的人物列和结束时间。</div>'}<section class="content-section"><div class="section-heading"><h3>音乐与歌词结构</h3><span>按真实时间轴</span></div><div class="music-map">${sections.map(item=>`<div><time>${duration(item.time)}</time><span class="energy" style="--energy:${Math.max(1,Number(item.energy||1))}"></span><strong>${escapeHtml(musicRoleName[item.music_role]||"音乐段落")}</strong>${editableContent(`music.section.${item.id}.emotion`,item.emotion,1)}</div>`).join("")||'<div class="empty-inline">尚未生成音乐结构</div>'}</div></section>`}
function renderStory(stage){const story=stage.data.story||{};const sections=story.sections||[];const characters=stage.data.characters||[];return `${contentEditBar(stage)}${stage.data.structural_test?'<div class="truth-banner warning">质量检查未通过：这只是自动测试生成的结构占位稿，不是正式故事方案，不能确认进入分镜制作。</div>':""}<section class="story-premise"><span>故事前提</span>${editableContent("story.premise",story.premise,2)}<p>${story.status==="draft_self_generated"?"当前为模型起草版本，需要您确认人物关系、情绪推进、高潮和结尾。":""}</p></section><section class="content-section"><div class="section-heading"><h3>情绪推进</h3><span>${sections.length} 个段落</span></div><div class="story-sections">${sections.map(item=>`<div><time>${duration(item.time)}</time>${editableContent(`story.section.${item.id}.emotion`,item.emotion,2)}<span>能量 ${escapeHtml(item.energy)} · 分镜 ${escapeHtml((item.shot_ids||[]).join("、"))}</span></div>`).join("")}</div></section><section class="content-section"><div class="section-heading"><h3>人物导演功能</h3><span>${characters.length} 个角色版本</span></div><div class="character-list">${characters.map(item=>`<article><img src="${fileUrl(item.source_asset)}" alt="${escapeHtml(item.name)}"><div><strong>${escapeHtml(item.name)}</strong>${editableContent(`character.${item.id}.director_function`,item.director_function,3)}${editableContent(`character.${item.id}.traits`,(item.traits||[]).join("、"),1)}</div></article>`).join("")}</div></section>`}
function renderStoryboard(stage){const shots=stage.data.shots||[];const preview=stage.artifacts?.find(path=>path.endsWith("animatic.mp4"));const lengths=shots.map(s=>Number(s.time?.[1]||0)-Number(s.time?.[0]||0));const longest=lengths.length?Math.max(...lengths):0;const average=lengths.length?lengths.reduce((a,b)=>a+b,0)/lengths.length:0;return `${contentEditBar(stage)}<div class="metric-row storyboard-metrics"><div><span>镜头总数</span><strong>${shots.length} 镜</strong></div><div><span>平均镜长</span><strong>${average.toFixed(2)} 秒</strong></div><div class="${longest>4?"metric-fail":""}"><span>最长镜头</span><strong>${longest.toFixed(2)} 秒</strong><small>${longest<=4?"符合短镜密度要求":"超过 4 秒，禁止确认"}</small></div></div>${preview?`<section class="animatic-preview"><div><span>结构粗剪</span><strong>先看片，再逐镜确认</strong><small>当前粗剪无声音，仅用于检查结构和节奏。</small></div><video controls playsinline preload="metadata" src="${fileUrl(preview)}#t=0.1"></video></section>`:""}<section class="content-section storyboard-section"><div class="section-heading"><h3>逐镜分镜</h3><span>${shots.length} 镜 · 按 Excel 歌词导演段拆解</span></div><div class="shot-list">${shots.map(renderShot).join("")||'<div class="empty-inline">尚未生成分镜</div>'}</div></section>`}
function renderShot(shot){const lyric=shot.lyric?.text||"纯音乐";const transition=shot.transition_out||{};const beat=shot.director_beat||{};const prefix=`shot.${shot.id}.`;return `<article class="shot-card"><header><div><span>分镜 ${escapeHtml(shot.id.replace(/^S/,""))} · ${duration(shot.time)}</span><strong>${escapeHtml(lyric)}</strong><small class="source-beat">${beat.source_row?`Excel 第 ${escapeHtml(beat.source_row)} 行 · 本段第 ${escapeHtml(beat.split_index)}/${escapeHtml(beat.split_count)} 镜 · 人物锁定`:"器乐过桥镜"}</small></div><b>能量 ${escapeHtml(shot.energy)}</b></header><div class="shot-body"><div class="shot-cast">${(shot.characters||[]).map(character=>`<figure><img src="${fileUrl(character.source_asset)}" alt="${escapeHtml(character.name)}"><figcaption>${escapeHtml(character.name)}</figcaption></figure>`).join("")}</div><div class="shot-direction"><dl><div><dt>镜头任务</dt><dd>${editableContent(prefix+"purpose",shot.purpose,3)}</dd></div><div><dt>画面动作</dt><dd>${editableContent(prefix+"primary_action",shot.primary_action,2)}</dd></div><div><dt>视觉推进</dt><dd>${(shot.visual_events||[]).map(item=>`<span class="visual-event">${Number(item.at||0).toFixed(2)}s · ${escapeHtml(item.event)}</span>`).join("")||"待编排"}</dd></div><div><dt>构图</dt><dd><span class="localized-enum">${escapeHtml(shotSizeName[shot.composition?.shot_size]||"待确定景别")}</span>${editableContent(prefix+"composition.arrangement",shot.composition?.arrangement,2)}</dd></div><div><dt>首帧</dt><dd>${editableContent(prefix+"first_frame",shot.first_frame,2)}</dd></div><div><dt>尾帧</dt><dd>${editableContent(prefix+"last_frame",shot.last_frame,2)}</dd></div><div><dt>转场</dt><dd><span class="localized-enum">${escapeHtml(transitionName[transition.type]||"待确定转场")}</span>${editableContent(prefix+"transition_out.shared_element",transition.shared_element,2)}</dd></div></dl></div><aside><span class="technique-tag">${escapeHtml(techniqueName[shot.technique]||"待定")}</span><strong>${shot.assets?.missing?.length?`${shot.assets.missing.length} 项素材缺失`:"素材齐全"}</strong><small>本镜费用 ${money(shot.cost_yuan)}</small></aside></div></article>`}
function renderKeyframes(stage){return `<section class="locked-work"><span>付费生成前的选择门</span><h3>${stage.status==="locked"?"确认分镜后，才会生成关键帧候选":"等待生成关键帧候选"}</h3><p>每个高风险镜头会先展示多张候选图。您选定首帧后，系统才能调用视频服务，避免对错误方案付费。</p><div class="candidate-placeholder"><div>候选一</div><div>候选二</div><div>候选三</div></div></section>`}
function backgroundLibrary(stage){const backgrounds=stage.data.backgrounds||[];return `<section class="content-section background-library"><div class="section-heading"><div><h3>背景与场景参考库</h3><span>用户原素材优先；没有现成背景时，分镜会明确标记为“待系统生成”</span></div><label class="compact-upload">补充背景参考<input type="file" accept="image/png,image/jpeg,image/webp" data-upload-background-library></label></div><div class="background-grid">${backgrounds.map(item=>`<figure><img src="${fileUrl(item.path)}" alt="背景参考"><figcaption><strong>${escapeHtml(item.name)}</strong><span>可在分镜中绑定到具体镜头</span></figcaption></figure>`).join("")||'<div class="empty-inline">当前没有用户背景参考。系统需要按分镜场景描述生成同画风背景。</div>'}</div></section>`}
const renderIntakeWithoutBackgrounds=renderIntake;
renderIntake=(stage)=>renderIntakeWithoutBackgrounds(stage)+backgroundLibrary(stage);
function shotReferencePanel(shot){const backgrounds=state.workflow?.stages?.find(item=>item.id==="storyboard")?.data?.backgrounds||[];const selected=shot.background?.reference||"";const selectedKeyframe=shot.selected_keyframe||"";return `<section class="shot-references"><div class="reference-column"><header><div><span>场景背景</span><strong>${selected?"已绑定背景参考":"待系统生成"}</strong></div><small>${selected?"重新生成或修改后需要复核分镜":"结合歌词、人物特点和前后镜生成同画风背景"}</small></header>${selected?`<img class="background-reference-image" src="${fileUrl(selected)}" alt="本镜背景参考">`:`<div class="reference-empty">${escapeHtml(chineseValue(shot.background?.description)||"尚未填写场景描述")}</div>`}<button class="generate-reference-button" type="button" data-generate-background="${escapeHtml(shot.id)}"><strong>用 GPT-image-2 生成背景</strong><span>¥0.50 / 张</span></button><label>从项目背景库选择<select data-shot-background="${escapeHtml(shot.id)}"><option value="">请选择背景</option>${backgrounds.map(item=>`<option value="${escapeHtml(item.path)}" ${item.path===selected?"selected":""}>${escapeHtml(item.name)}</option>`).join("")}</select></label><label class="compact-upload">上传自己的背景<input type="file" accept="image/png,image/jpeg,image/webp" data-upload-shot-background="${escapeHtml(shot.id)}"></label></div><div class="reference-column composite-reference"><header><div><span>人物＋背景组合首帧</span><strong>${selectedKeyframe?"已选择完整场景":"尚未补充"}</strong></div><small>背景确认且分镜批准后，生成包含人物、构图与光线的最终参考</small></header>${selectedKeyframe?`<img class="keyframe-reference-image" src="${fileUrl(selectedKeyframe)}" alt="已选完整场景首帧">`:'<div class="reference-empty">请先确认分镜，再到关键帧步骤生成完整场景首帧</div>'}<label class="compact-upload">上传组合首帧候选<input type="file" accept="image/png,image/jpeg,image/webp" data-upload-keyframe="${escapeHtml(shot.id)}"></label></div></section>`}
const renderShotWithoutReferences=renderShot;
renderShot=(shot)=>renderShotWithoutReferences(shot).replace("</article>",shotReferencePanel(shot)+"</article>");
renderKeyframes=(stage)=>{const shots=stage.data.shots||[];return `<section class="keyframe-workbench"><header class="keyframe-summary"><div><span>完整场景首帧确认门</span><h3>${stage.data.selected_count||0} / ${stage.data.total_count||0} 镜已选择</h3><p>每张候选必须同时包含已确认人物、背景、构图和光线关系。只有全部选定并确认后，单镜视频才会开放。</p></div><strong>${stage.status==="locked"?"等待分镜确认":stage.status==="approved"?"已经确认":"正在补齐"}</strong></header><div class="keyframe-shot-list">${shots.map(shot=>`<article><header><div><span>分镜 ${escapeHtml(shot.id)}</span><strong>${escapeHtml(shot.lyric?.text||"纯音乐")}</strong></div><small>${shot.background?.reference?"已绑定背景参考":"背景待系统生成"}</small></header><div class="keyframe-candidates">${(shot.keyframes||[]).map(path=>`<label class="keyframe-candidate ${path===shot.selected_keyframe?"selected":""}"><input type="radio" name="keyframe-${escapeHtml(shot.id)}" value="${escapeHtml(path)}" data-select-keyframe="${escapeHtml(shot.id)}" ${path===shot.selected_keyframe?"checked":""}><img src="${fileUrl(path)}" alt="完整场景首帧候选"><span>${path===shot.selected_keyframe?"当前选择":"选择此图"}</span></label>`).join("")||'<div class="reference-empty">当前没有完整场景候选</div>'}<button class="keyframe-generate" type="button" data-generate-keyframe="${escapeHtml(shot.id)}" ${!shot.background?.reference||stage.status==="locked"?"disabled":""}><strong>用 GPT-image-2 生成</strong><span>${shot.background?.reference?"¥0.50 / 张":"请先补背景"}</span></button><label class="keyframe-upload">＋<span>上传候选</span><input type="file" accept="image/png,image/jpeg,image/webp" data-upload-keyframe="${escapeHtml(shot.id)}"></label></div></article>`).join("")||'<div class="empty-inline">尚未生成分镜</div>'}</div></section>`}
function renderShots(stage){return `<section class="locked-work"><span>逐镜制作与诊断</span><h3>${escapeHtml(stage.data.reason||"等待关键帧批准")}</h3><p>正式流程中，每个镜头都会显示生成预览、费用、诊断结论和返修记录。所有镜头经您确认后才进入合成。</p><div class="progress-placeholder"><span style="width:${stage.data.generated_count&&stage.data.shot_count?stage.data.generated_count/stage.data.shot_count*100:0}%"></span></div><small>${stage.data.generated_count||0} / ${stage.data.shot_count||0} 镜完成</small></section>`}
function videoGallery(paths,label){return paths?.length?`<div class="video-gallery">${paths.map(path=>`<figure><video controls playsinline preload="metadata" src="${fileUrl(path)}#t=0.1"></video><figcaption><strong>${escapeHtml(label)}</strong><span>${escapeHtml(path.split("/").pop())}</span></figcaption></figure>`).join("")}</div>`:'<div class="empty-inline">暂无视频产物</div>'}
function renderComposite(stage){const data=stage.data||{};const qc=data.qc||{};return `${data.automated_test?'<div class="truth-banner warning">这里的成片来自“两镜自动测试”，使用本地角色源图和确定性渲染；没有调用图片或视频生成服务，不能代表正式制作流程已完成。</div>':""}${videoGallery(data.finals,"两镜测试成片")}<section class="qc-strip"><div><span>画幅</span><strong>${qc.width||"-"} × ${qc.height||"-"}</strong></div><div><span>时长</span><strong>${qc.duration?Number(qc.duration).toFixed(1)+" 秒":"-"}</strong></div><div><span>检查结果</span><strong>${escapeHtml(qcName[qc.status]||"待检查")}</strong></div><div><span>声音</span><strong>${qc.audio_present?"有":"粗剪无声"}</strong></div></section>`}
function renderDelivery(stage){return `${stage.data.automated_test?'<div class="truth-banner warning">自动测试产物仅供功能验收。确认交付不会把它自动发布到任何外部平台。</div>':""}${videoGallery(stage.data.finals,"待确认版本")}`}
function renderStage(stage){let body="";if(stage.id==="intake")body=renderIntake(stage);else if(stage.id==="music")body=renderMusic(stage);else if(stage.id==="story")body=renderStory(stage);else if(stage.id==="storyboard")body=renderStoryboard(stage);else if(stage.id==="keyframes")body=renderKeyframes(stage);else if(stage.id==="shots")body=renderShots(stage);else if(stage.id==="composite")body=renderComposite(stage);else body=renderDelivery(stage);return stageHead(stage)+nextStepBlock(stage)+body+approvalBlock(stage)+promptBlock(stage)+artifactBlock(stage)}

function bindStageActions(stage){document.querySelectorAll("details[data-panel]").forEach(panel=>panel.addEventListener("toggle",()=>{state.openPanels[panel.dataset.panel]=panel.open}));document.querySelectorAll("[data-remove-asset]").forEach(button=>button.addEventListener("click",()=>{state.assetToRemove={relative_path:button.dataset.removeAsset,name:button.dataset.assetName};$("asset-remove-name").textContent=state.assetToRemove.name;$("asset-remove-path").textContent=state.assetToRemove.relative_path;showDialog("asset-remove-dialog")}));document.querySelectorAll("[data-restore-asset]").forEach(button=>button.addEventListener("click",async()=>{button.disabled=true;try{state.workflow=await api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/assets/characters/restore`,{method:"POST",body:JSON.stringify({relative_path:button.dataset.restoreAsset})});renderWorkflow();toast("人物图片已恢复，请重新运行素材分析")}catch(error){toast(error.message)}finally{button.disabled=false}}));document.querySelectorAll("[data-decision]").forEach(button=>button.addEventListener("click",async()=>{const action=button.dataset.decision;const note=$("decision-note")?.value.trim()||"";if(action==="request_revision"&&!note){toast("请填写需要修改的内容");return}button.disabled=true;try{state.workflow=await api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/workflow/${encodeURIComponent(stage.id)}/decision`,{method:"POST",body:JSON.stringify({action,note})});state.selectedStage=action==="approve"?(stage.id==="story"?"storyboard":stage.id==="storyboard"?"keyframes":stage.id==="keyframes"?"shots":stage.id):stage.id;renderWorkflow();toast(action==="approve"?"已记录您的确认":"已记录修改意见")}catch(error){toast(error.message)}finally{button.disabled=false}}));document.querySelectorAll("[data-resume-planning]").forEach(button=>button.addEventListener("click",()=>resumePlanning(button)));document.querySelectorAll("[data-save-prompts]").forEach(button=>button.addEventListener("click",()=>savePrompts(button)));document.querySelectorAll("[data-localize-content]").forEach(button=>button.addEventListener("click",()=>localizeContent(button)));document.querySelectorAll("[data-save-content]").forEach(button=>button.addEventListener("click",()=>saveDisplayContent(button)))}
async function savePrompts(button){const prompts={};for(const workflowStage of state.workflow.stages)for(const item of workflowStage.prompts||[]){prompts[item.key]=item.task_text;prompts[`system::${item.key}`]=item.system_text;prompts["prompt.translate_requested"]=item.translation.task_text;prompts["system::prompt.translate_requested"]=item.translation.system_text}document.querySelectorAll("[data-prompt-task]").forEach(node=>prompts[node.dataset.promptTask]=node.value);document.querySelectorAll("[data-prompt-system]").forEach(node=>prompts[`system::${node.dataset.promptSystem}`]=node.value);const translationTask=document.querySelector("[data-translation-task]");const translationSystem=document.querySelector("[data-translation-system]");if(translationTask)prompts["prompt.translate_requested"]=translationTask.value;if(translationSystem)prompts["system::prompt.translate_requested"]=translationSystem.value;button.disabled=true;try{const result=await api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/prompts`,{method:"PUT",body:JSON.stringify({prompts})});for(const workflowStage of state.workflow.stages)for(const item of workflowStage.prompts||[]){item.task_text=result.prompts[item.key];item.text=item.task_text;item.system_text=result.prompts[`system::${item.key}`];item.translation.task_text=result.prompts["prompt.translate_requested"];item.translation.system_text=result.prompts["system::prompt.translate_requested"]}renderWorkflow();toast("中文系统提示词与任务提示词已保存")}catch(error){toast(error.message)}finally{button.disabled=false}}

async function localizeContent(button){button.disabled=true;button.textContent="正在生成中文稿";try{state.workflow=await api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/display-content/localize`,{method:"POST"});renderWorkflow();toast("中文展示稿已生成，翻译费用已记录")}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent="生成中文展示稿"}}
async function saveDisplayContent(button){const fields={};document.querySelectorAll("[data-content-field]").forEach(node=>{const value=node.value.trim();if(value)fields[node.dataset.contentField]=value});if(!Object.keys(fields).length){toast("请先生成或填写中文内容");return}button.disabled=true;button.textContent="正在生成英文执行稿";try{state.workflow=await api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/display-content`,{method:"PUT",body:JSON.stringify({fields})});renderWorkflow();renderCosts();toast("中文修改已保存，英文执行稿与翻译费用已更新")}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent="保存中文修改"}}

function renderJobs(){const list=$("job-list");if(!state.jobs.length){list.innerHTML='<div class="empty-inline">当前项目还没有运行记录</div>';return}const pages=Math.max(1,Math.ceil(state.jobs.length/state.pageSize));state.jobPage=Math.min(Math.max(1,state.jobPage),pages);const start=(state.jobPage-1)*state.pageSize;const rows=state.jobs.slice(start,start+state.pageSize).map(item=>{const spec=item.job_spec,status=item.status.runtime_state;return `<div class="job-item"><div><strong>${escapeHtml(operationName[spec.operation]||spec.operation)}</strong><code>${escapeHtml(shortId(spec.job_id))}</code></div><span class="mini-status ${escapeHtml(status)}">${escapeHtml(statusName[status]||status)}</span></div>`}).join("");list.innerHTML=rows+pagination(state.jobPage,state.jobs.length,state.pageSize,"jobs")}
async function loadProjects(){try{state.projects=await api("/api/v1/projects");setConnection(true);if(!state.project&&state.projects.length)await selectProject(state.projects[0].project_id);else{renderProjects();renderProjectView()}}catch(error){setConnection(false);toast(error.message)}}
async function selectProject(projectId){const project=state.projects.find(item=>item.project_id===projectId);if(!project)return;state.project=project;state.selectedStage=null;state.jobPage=1;state.costPage=1;renderProjects();try{[state.workflow,state.jobs]=await Promise.all([api(`/api/v1/projects/${encodeURIComponent(projectId)}/workflow`),api(`/api/v1/projects/${encodeURIComponent(projectId)}/jobs`)]);state.project.display_name=state.workflow.project?.display_name||state.project.slug;renderProjects();renderProjectView()}catch(error){toast(error.message)}}
async function refresh(silent=false){if(!state.project)return;try{[state.workflow,state.jobs]=await Promise.all([api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/workflow`),api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/jobs`)]);renderProjectView();if(!silent)toast("制作进度已刷新")}catch(error){if(!silent)toast(error.message)}}
async function digest(value){const bytes=new TextEncoder().encode(JSON.stringify(value));const hash=await crypto.subtle.digest("SHA-256",bytes);return `sha256:${[...new Uint8Array(hash)].map(item=>item.toString(16).padStart(2,"0")).join("")}`}

function folderAssetKind(file){const relative=String(file.webkitRelativePath||file.name);const image=/\.(png|jpe?g|webp)$/i.test(file.name);return image&&/(^|[\\/])(背景|场景|环境|backgrounds?|scenes?|locations?)([\\/]|$)/i.test(relative)?"backgrounds":""}
async function importBackgroundFile(file){return api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/assets?filename=${encodeURIComponent(file.name)}&kind=backgrounds`,{method:"POST",headers:{"Content-Type":file.type||"application/octet-stream"},body:file})}
async function uploadKeyframe(shotId,file){state.workflow=await api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/shots/${encodeURIComponent(shotId)}/keyframes?filename=${encodeURIComponent(file.name)}`,{method:"POST",headers:{"Content-Type":file.type||"application/octet-stream"},body:file});renderWorkflow();toast("完整场景首帧候选已加入并选中")}
async function generateShotImage(button,kind){if(!state.project)return;const shotId=kind==="background"?button.dataset.generateBackground:button.dataset.generateKeyframe;if(!shotId)return;const original=button.innerHTML;button.disabled=true;button.textContent=kind==="background"?"正在生成背景":"正在生成组合首帧";try{state.workflow=await api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/shots/${encodeURIComponent(shotId)}/${kind==="background"?"background":"keyframes"}/generate`,{method:"POST"});state.selectedStage=kind==="background"?"storyboard":"keyframes";renderWorkflow();renderCosts();toast(`${kind==="background"?"背景":"组合首帧"}已生成并登记 ¥0.50 费用`)}catch(error){toast(error.message)}finally{if(button.isConnected){button.disabled=false;button.innerHTML=original}}}
document.addEventListener("change",async(event)=>{const node=event.target;if(node.matches("[data-upload-background-library]")){const file=node.files?.[0];if(!file)return;node.disabled=true;try{await importBackgroundFile(file);await refresh(true);renderWorkflow();toast("背景参考已加入项目素材库")}catch(error){toast(error.message)}finally{node.disabled=false;node.value=""}}else if(node.matches("[data-upload-shot-background]")){const file=node.files?.[0];if(!file)return;node.disabled=true;try{const imported=await importBackgroundFile(file);state.workflow=await api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/shots/${encodeURIComponent(node.dataset.uploadShotBackground)}/background`,{method:"PUT",body:JSON.stringify({relative_path:imported.relative_path})});renderWorkflow();toast("本镜背景参考已绑定，请重新核对分镜")}catch(error){toast(error.message)}finally{node.disabled=false;node.value=""}}else if(node.matches("[data-shot-background]")){if(!node.value)return;node.disabled=true;try{state.workflow=await api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/shots/${encodeURIComponent(node.dataset.shotBackground)}/background`,{method:"PUT",body:JSON.stringify({relative_path:node.value})});renderWorkflow();toast("背景参考已绑定，请重新核对分镜")}catch(error){toast(error.message)}finally{node.disabled=false}}else if(node.matches("[data-upload-keyframe]")){const file=node.files?.[0];if(!file)return;node.disabled=true;try{await uploadKeyframe(node.dataset.uploadKeyframe,file)}catch(error){toast(error.message)}finally{node.disabled=false;node.value=""}}else if(node.matches("[data-select-keyframe]")){node.disabled=true;try{state.workflow=await api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/shots/${encodeURIComponent(node.dataset.selectKeyframe)}/keyframes/selection`,{method:"PUT",body:JSON.stringify({relative_path:node.value})});renderWorkflow();toast("完整场景首帧选择已更新")}catch(error){toast(error.message)}finally{node.disabled=false}}});
document.addEventListener("click",event=>{const background=event.target.closest?.("[data-generate-background]");if(background&&!background.disabled){void generateShotImage(background,"background");return}const keyframe=event.target.closest?.("[data-generate-keyframe]");if(keyframe&&!keyframe.disabled)void generateShotImage(keyframe,"keyframe")});

function showDialog(id){$(id).showModal()}function closeDialogs(){document.querySelectorAll("dialog[open]").forEach(dialog=>dialog.close())}
$("project-form").addEventListener("submit",async(event)=>{event.preventDefault();const form=new FormData(event.currentTarget);const title=String(form.get("title")||"").trim();const slug=String(form.get("slug")||"").trim();try{const created=await api("/api/v1/projects",{method:"POST",body:JSON.stringify({slug,brief:{title,canvas:form.get("canvas"),target_platforms:[form.get("platform")]}})});closeDialogs();await loadProjects();await selectProject(created.project_id);toast("项目已创建，请导入素材")}catch(error){toast(error.message)}});
$("job-form").addEventListener("submit",async(event)=>{event.preventDefault();if(!state.project)return;const formNode=event.currentTarget;const submit=formNode.querySelector('button[type="submit"]');const files=[...formNode.elements.asset_folder.files];if(!files.length){toast("请选择项目素材文件夹");return}submit.disabled=true;submit.textContent="正在导入";try{const imported=[];for(let index=0;index<files.length;index+=1){const file=files[index];const kind=folderAssetKind(file);submit.textContent=`正在导入 ${index+1}/${files.length}`;const result=await api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/assets?filename=${encodeURIComponent(file.name)}${kind?`&kind=${kind}`:""}`,{method:"POST",headers:{"Content-Type":file.type||"application/octet-stream"},body:file});if(!result.ignored)imported.push(result)}const byKind=imported.reduce((all,item)=>{(all[item.kind]||=[]).push(item);return all},{});if((byKind.audio||[]).length!==1)throw new Error("文件夹中需要且只能有一个音频文件");if((byKind.lyrics||[]).length!==1)throw new Error("文件夹中需要且只能有一个歌词文件（xlsx、lrc 或 txt）");if(!(byKind.characters||[]).length)throw new Error("文件夹中没有识别到角色图片");const refs=imported.filter(item=>item.kind!=="backgrounds").map(item=>item.relative_path);const operation="analyze";const created=await api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/jobs`,{method:"POST",body:JSON.stringify({operation,input_digest:await digest({operation,refs}),input_refs:refs,auto_start:false})});if(created.status.runtime_state==="queued")await api(`/api/v1/jobs/${encodeURIComponent(created.job_spec.job_id)}/director/intake`,{method:"POST"});closeDialogs();formNode.reset();await refresh(true);state.selectedStage="intake";renderWorkflow();toast(`素材已识别：人物 ${(byKind.characters||[]).length} 张，背景 ${(byKind.backgrounds||[]).length} 张`)}catch(error){toast(error.message)}finally{submit.disabled=false;submit.textContent="创建任务"}});
$("job-form").elements.asset_folder.addEventListener("change",event=>{const files=[...event.currentTarget.files].filter(file=>!file.name.startsWith("."));const backgrounds=files.filter(file=>folderAssetKind(file)==="backgrounds").length;$("folder-summary").textContent=files.length?`已选择 ${files.length} 个文件${backgrounds?`，其中背景/场景参考 ${backgrounds} 张`:""}；系统会自动区分音频、歌词、人物与背景`:`系统会读取子文件夹并自动识别素材，不会上传文件夹路径。`});
$("run-mvp-button").addEventListener("click",async(event)=>{if(!state.project)return;const button=event.currentTarget;const source=state.jobs.find(item=>item.job_spec.operation==="analyze"&&item.status.runtime_state==="succeeded"&&item.job_spec.input_refs.length);if(!source){toast("请先完成素材分析");return}button.disabled=true;button.textContent="自动测试运行中";try{const refs=[...source.job_spec.input_refs];const prompts={};for(const stage of state.workflow.stages)for(const item of stage.prompts||[]){prompts[item.key]=item.task_text;prompts[`system::${item.key}`]=item.system_text;prompts["prompt.translate_requested"]=item.translation.task_text;prompts["system::prompt.translate_requested"]=item.translation.system_text}const created=await api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/jobs`,{method:"POST",body:JSON.stringify({operation:"animatic",input_digest:await digest({operation:"animatic",refs,prompts,run_id:new Date().toISOString()}),input_refs:refs,requested_outputs:["outputs/final_mvp.mp4"],auto_start:false})});await api(`/api/v1/jobs/${encodeURIComponent(created.job_spec.job_id)}/director/mvp-test`,{method:"POST"});await refresh(true);state.selectedStage="composite";renderWorkflow();toast("两镜自动测试已完成")}catch(error){await refresh(true).catch(()=>{});toast(error.message)}finally{button.disabled=false;button.textContent="运行两镜自动测试"}});
$("delete-form").addEventListener("submit",async(event)=>{event.preventDefault();if(!state.project)return;const form=event.currentTarget;const confirmation=new FormData(form).get("confirmation_slug");if(confirmation!==state.project.slug){toast("项目标识不匹配");return}try{await api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}`,{method:"DELETE",body:JSON.stringify({confirmation_slug:confirmation})});closeDialogs();state.project=null;state.workflow=null;state.jobs=[];await loadProjects();toast("项目已彻底删除")}catch(error){toast(error.message)}});
$("asset-remove-form").addEventListener("submit",async(event)=>{event.preventDefault();if(!state.project||!state.assetToRemove)return;const button=event.currentTarget.querySelector('button[type="submit"]');button.disabled=true;try{state.workflow=await api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/assets/characters/remove`,{method:"POST",body:JSON.stringify({relative_path:state.assetToRemove.relative_path,confirmation_name:state.assetToRemove.name})});closeDialogs();state.assetToRemove=null;state.selectedStage="intake";renderWorkflow();toast("图片已移入项目回收区，后续方案已标记为需要重新生成")}catch(error){toast(error.message)}finally{button.disabled=false}});

function populateSettings(settings){state.settings=settings;const form=$("settings-form");$("setting-workspace").value=settings.paths.workspace_root;$("workspace-state").textContent=settings.paths.workspace_change_pending?`等待重启，当前仍使用 ${settings.paths.active_workspace_root}`:"当前正在使用此工作区";$("workspace-state").className=settings.paths.workspace_change_pending?"field-note pending":"field-note";for(const key of ["ffmpeg_path","ffprobe_path","whisper_model_path"])form.elements[key].value=settings.paths[key]||"";for(const provider of ["llm","image","video"]){form.elements[`${provider}_base_url`].value=settings[provider].base_url||"";form.elements[`${provider}_model`].value=settings[provider].model||"";form.elements[`${provider}_api_key`].value="";$(`${provider}-key-state`).textContent=settings[provider].api_key_configured?`已读取 ${settings[provider].api_key_hint}`:"尚未配置";const node=$(`${provider}-provider-state`);node.textContent=settings[provider].ready?"已就绪":"待配置";node.className=`provider-state ${settings[provider].ready?"ready":"missing"}`}const toolCount=[settings.paths.ffmpeg_detected,settings.paths.ffprobe_detected,settings.paths.whisper_configured].filter(Boolean).length;$("local-tools-state").textContent=`已自动识别 ${toolCount}/3`;$("config-state").textContent=settings.paths.workspace_change_pending?"待重启":"已读取";$("config-state").className=settings.paths.workspace_change_pending?"pending":"ready"}
function populateLogs(logs){state.logs=logs;$("backend-log-path").textContent=logs.backend;$("frontend-log-path").textContent=logs.frontend}
async function openSettings(){try{populateSettings(await api("/api/v1/settings"));populateLogs(await api("/api/v1/logs"));showDialog("settings-dialog")}catch(error){toast(error.message)}}
$("settings-form").addEventListener("submit",async(event)=>{event.preventDefault();const form=event.currentTarget;const value={paths:{workspace_root:form.elements.workspace_root.value,ffmpeg_path:form.elements.ffmpeg_path.value,ffprobe_path:form.elements.ffprobe_path.value,whisper_model_path:form.elements.whisper_model_path.value}};for(const provider of ["llm","image","video"])value[provider]={base_url:form.elements[`${provider}_base_url`].value,model:form.elements[`${provider}_model`].value,api_key:form.elements[`${provider}_api_key`].value};try{populateSettings(await api("/api/v1/settings",{method:"PUT",body:JSON.stringify(value)}));closeDialogs();toast(state.settings.paths.workspace_change_pending?"工作区已保存，重启服务后生效":"系统配置已保存")}catch(error){toast(error.message)}});
document.addEventListener("click",event=>{const button=event.target.closest?.("[data-page-kind]");if(!button||button.disabled)return;const page=Number(button.dataset.pageValue);if(!Number.isInteger(page)||page<1)return;if(button.dataset.pageKind==="jobs"){state.jobPage=page;renderJobs()}else if(button.dataset.pageKind==="costs"){state.costPage=page;renderCosts()}});
const pause=milliseconds=>new Promise(resolve=>setTimeout(resolve,milliseconds));
$("restart-service-button").addEventListener("click",async(event)=>{const button=event.currentTarget;button.disabled=true;button.textContent="正在重启";try{await api("/api/v1/system/restart",{method:"POST"});closeDialogs();setConnection(false);toast("服务正在重启");await pause(1200);for(let attempt=0;attempt<40;attempt+=1){try{const response=await fetch("/readyz",{cache:"no-store"});if(response.ok){window.location.reload();return}}catch{}await pause(500)}throw new Error("服务重启超时，请重新打开页面")}catch(error){button.disabled=false;button.textContent="重启服务";toast(error.message)}});

async function resumePlanning(button){const sourceJobId=button.dataset.resumePlanning;if(!sourceJobId)return;button.disabled=true;button.textContent="模型流式生成中";toast("模型正在流式生成视觉总谱，页面会持续刷新任务状态");try{const result=await api(`/api/v1/jobs/${encodeURIComponent(sourceJobId)}/director/plan/resume`,{method:"POST"});await refresh(true);state.selectedStage="music";renderWorkflow();toast(`续跑完成：${shortId(result.job_id)}`)}catch(error){await refresh(true).catch(()=>{});state.selectedStage="music";renderWorkflow();toast(error.message)}finally{button.disabled=false;button.textContent="从失败步骤继续"}}

async function runPlanning(button){const intake=state.workflow.stages.find(item=>item.id==="intake")?.data?.manifest||{};const refs=[intake.audio?.path,intake.lyrics?.path,...(intake.characters||[]).map(item=>item.path)].filter(Boolean);if(!intake.audio?.path||!intake.lyrics?.path||!(intake.characters||[]).length){toast("素材不完整，请重新导入音频、歌词和人物图");return}const prompts={};for(const stage of state.workflow.stages)for(const item of stage.prompts||[]){prompts[item.key]=item.task_text;prompts[`system::${item.key}`]=item.system_text;prompts["prompt.translate_requested"]=item.translation.task_text;prompts["system::prompt.translate_requested"]=item.translation.system_text}button.disabled=true;button.textContent="模型流式生成中";try{const created=await api(`/api/v1/projects/${encodeURIComponent(state.project.project_id)}/jobs`,{method:"POST",body:JSON.stringify({operation:"animatic",input_digest:await digest({operation:"planning",refs,prompts,run_id:new Date().toISOString()}),input_refs:refs,requested_outputs:["creative/music_map.yaml","creative/story_framework.yaml","creative/visual_score.yaml"],auto_start:false})});await refresh(true);state.selectedStage="music";renderWorkflow();toast("模型正在流式分析音乐、歌词、人物关系与分镜");await api(`/api/v1/jobs/${encodeURIComponent(created.job_spec.job_id)}/director/plan`,{method:"POST"});await refresh(true);state.selectedStage="music";renderWorkflow();toast("音乐、故事和分镜草稿已生成，请先检查音乐与歌词")}catch(error){await refresh(true).catch(()=>{});toast(error.message)}finally{button.disabled=false;button.textContent="开始分析音乐与歌词"}}

$("new-project-button").addEventListener("click",()=>showDialog("project-dialog"));$("empty-create-button").addEventListener("click",()=>showDialog("project-dialog"));$("new-job-button").addEventListener("click",()=>showDialog("job-dialog"));$("delete-project-button").addEventListener("click",()=>{if(!state.project)return;$("delete-slug-label").textContent=state.project.slug;$("delete-form").reset();showDialog("delete-dialog")});$("refresh-button").addEventListener("click",()=>refresh());$("settings-button").addEventListener("click",openSettings);document.querySelectorAll("[data-close]").forEach(button=>button.addEventListener("click",closeDialogs));document.querySelectorAll("dialog").forEach(dialog=>dialog.addEventListener("click",event=>{if(event.target===dialog)dialog.close()}));document.addEventListener("click",event=>{const button=event.target.closest?.("[data-run-planning]");if(button&&!button.disabled)void runPlanning(button)});window.addEventListener("error",event=>void reportFrontendError({message:event.message||event.error?.message||"脚本执行错误",path:location.pathname,method:"SCRIPT",status:0}));window.addEventListener("unhandledrejection",event=>void reportFrontendError({message:event.reason?.message||String(event.reason||"未处理的 Promise 错误"),path:location.pathname,method:"PROMISE",status:0}));loadProjects();setInterval(()=>{if(state.jobs.some(item=>item.status.runtime_state==="running"))refresh(true).catch(()=>{})},1800);
